/bin/zsh -c "python3 - <<'PY'
from fractions import Fraction
for p in [2,3,5,7,11]:
    for delta in [Fraction(0),Fraction(1,p**2),Fraction(1,p),Fraction(1)]:
        lhs=(1-Fraction(1,p**2))**2*(1+Fraction(p**2*delta-1,(p**2-1)**2))
        rhs=(1-Fraction(2,p**2))*(1+delta/Fraction(p**2-2))
        assert lhs==rhs
for d in range(1,9):
    for H in [1,2,10,1000]:
        assert sum(h**(-1+1/d) for h in range(1,H+1)) <= d*H**(1/d)+1e-9
print('Checked the local-factor identity exactly for five primes and four rational densities; checked the power-sum bound for d=1,...,8 and H=1,2,10,1000.')
PY"

